window.OBSIDIAN_DOCS_CHUNK=window.OBSIDIAN_DOCS_CHUNK||{};window.OBSIDIAN_DOCS_CHUNK["lowalt"]={"低空经济/低空经济专题.md":"<h1 style=\"font-size:19px;font-weight:800;margin:18px 0 10px;color:#16233B;\">低空经济专题</h1><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">上级：徐总的知识库</p><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">这个专题用于沉淀低空经济、低空物流、空域审批、军地协调、企业合作模式等知识。</p><hr style=\"border:none;border-top:1px solid #E3E8F0;margin:18px 0;\"><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">📂 目录结构</h2><pre style=\"background:#0F1B33;color:#D8E2F5;border-radius:12px;padding:14px;font-size:12.5px;line-height:1.7;overflow-x:auto;margin:14px 0;white-space:pre-wrap;word-break:break-word;\">低空经济/\n├── 低空经济专题.md                      ← 本文件，专题总览\n├── 成都首条常态化低空城市物流航线          ← 📰 新闻原文\n├── 成都双流低空物流航线空域审批深度分析     ← 📊 深度分析\n├── 空天智航与丰翼合作模式分析              ← 💡 自行推演\n├── 蜀道集团低空经济：无人机巡检·招投标采购与产业协作体系 ← 💡 蜀道低空全景（技术+招投标+生态）\n└── 蜀道集团大疆无人机巡检：采购投资与融资租赁测算 ← 📊 投资与融资测算（财务层·另文）\n</pre><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">📄 笔记清单</h2><div style=\"overflow-x:auto;margin:14px 0;\"><table style=\"width:100%;border-collapse:collapse;font-size:12.5px;\"><tbody><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">笔记</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">类型</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">核心价值</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">成都首条常态化低空城市物流航线</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">📰 新闻原文</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">原始新闻素材，含公开披露的审批表述（西部战区批复、ARK40参数、安全设计）</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">成都双流低空物流航线空域审批深度分析</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">📊 深度分析</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">空域审批路径方法论——\"政府搭台、企业主申、军方批复、平台监管\"的四层模型</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">空天智航与丰翼合作模式分析</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">💡 自行推演</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">\"联合体\"模式——空天智航是属地承接方、丰翼是技术输出方，军方认可的是\"责任共同体\"</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">蜀道集团低空经济：无人机巡检·招投标采购与产业协作体系</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">💡 蜀道低空全景</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">蜀交低空公司（蜀道智巡同主体）合册：技术层（大疆硬件+凌次方飞控+蜀道智巡三层架构、算法归属纠偏）+ 招投标采购层（江油市无人机及配套设施采购中标候选公示、协作单位资源库公开遴选）+ 生态/平台化解读</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">蜀道集团大疆无人机巡检：采购投资与融资租赁测算</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">📊 投资与融资测算</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">蜀道大疆机场3 采购的 NPV 三方案对比（自购 +59.1 万 / 融资租赁 +67.8 万 / 维持人工 -102.3 万）、盈亏平衡 8.8 万/年、融资租赁产权与分期解读；iMA 金融视角内容待凭证刷新后补充</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">低空经济法律体系：按层级梳理对社会经济政治的影响</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">📋 框架应用</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">政策传导逻辑主线（决定→意见→规划→方案→立法），低空经济是演示载体——看清低空政策\"从上往下怎么传\"的合规入口</td></tr></tbody></table></div><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">🔗 笔记关系链</h2><pre style=\"background:#0F1B33;color:#D8E2F5;border-radius:12px;padding:14px;font-size:12.5px;line-height:1.7;overflow-x:auto;margin:14px 0;white-space:pre-wrap;word-break:break-word;\">新闻原文 ──→ 提供了事实基础\n    │\n    ▼\n空域审批分析 ──→ 提炼了审批方法论\n    │\n    ▼\n合作模式分析 ──→ 深入推演了企业分工逻辑\n</pre><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">三条笔记逐层深入，从事实到方法论再到模式推演。另，蜀道集团低空经济：无人机巡检·招投标采购与产业协作体系 把蜀道低空从\"审批/合作\"轴切到\"技术架构/算法归属 + 招投标采购 + 生态平台化\"轴，合册呈现蜀交低空（蜀道智巡同主体）从单套巡检系统走向低空经济平台的完整路径；其财务层（大疆机场3 采购 NPV 测算）另见 蜀道集团大疆无人机巡检：采购投资与融资租赁测算。</p><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">📌 可补充方向</h2><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">[ ] 其他城市低空物流案例（深圳、广州等）</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">[x] 无人机型号/技术对比（部分）：已有 蜀道集团低空经济：无人机巡检·招投标采购与产业协作体系 覆盖大疆机场3 / M4TD / M400 + 通用版/适配版算法分层；更广的跨厂商型号横向对比仍可补</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">[ ] 国家层面低空经济政策梳理</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">[ ] 空域审批法规原文及解读</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">[x] 低空经济法律体系已建专题笔记：低空经济法律体系：按层级梳理对社会经济政治的影响（法律/ 下，已对照腾讯文档《低空领域相关部门和资源》核实补全）</li></ul><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">📏 维护规则</h2><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">新闻原文、政策材料、案例分析、方法论总结都放入 <code style=\"background:#EEF1F8;padding:1px 5px;border-radius:4px;font-size:0.9em;color:#2563EB;\">低空经济/</code></li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">新增笔记后同步更新本专题入口和全库 <code style=\"background:#EEF1F8;padding:1px 5px;border-radius:4px;font-size:0.9em;color:#2563EB;\">知识库索引.md</code></li></ul><hr style=\"border:none;border-top:1px solid #E3E8F0;margin:18px 0;\"><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">总库：徐总的知识库</p>","低空经济/成都双流低空物流航线空域审批深度分析.md":"<h1 style=\"font-size:19px;font-weight:800;margin:18px 0 10px;color:#16233B;\">成都双流低空物流航线空域审批深度分析</h1><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\"><b>分析来源：</b> ChatGPT 深度分析 | <b>归档日期：</b> 2026-05-26</p><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\"><b>关联笔记：</b> 成都首条常态化低空城市物流航线、低空经济法律体系：按层级梳理对社会经济政治的影响、中国立法体系总览</p><hr style=\"border:none;border-top:1px solid #E3E8F0;margin:18px 0;\"><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\"><b>tags:</b> 低空经济, 空域审批, 空域申请, 西部战区, 军方批复, 政府背书, 固定航线, 成都, 双流</p><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">核心判断：这不是企业单独申请，而是政府+企业+军方的混合型模式</h2><blockquote style=\"background:#EAF1FE;border-left:3px solid #2563EB;border-radius:0 10px 10px 0;padding:12px 14px;margin:14px 0;font-size:13.5px;line-height:1.8;color:#1E3A5F;\">地方政府招引企业 → 企业提出场景与航线方案 → 企业/技术方完成航线设计与安全论证 → 地方政府体系背书协调 → 西部战区空军某部航管处批复 → 企业进入常态化运行与飞行计划报备</blockquote><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">它更像是 <b>政府搭台、企业主申、军方批复、平台监管</b> 的混合型模式。</p><hr style=\"border:none;border-top:1px solid #E3E8F0;margin:18px 0;\"><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">一、这次申请的性质：固定航线常态化运行</h2><h3 style=\"font-size:15px;font-weight:700;margin:20px 0 8px;color:#1E3A5F;\">审批特征</h3><div style=\"overflow-x:auto;margin:14px 0;\"><table style=\"width:100%;border-collapse:collapse;font-size:12.5px;\"><tbody><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">维度</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">具体情况</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">审批含义</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">航线数量</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">首期3条固定低空城市物流航线</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">非单次飞行，是固定航线</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">飞行频次</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">首日50架次，常态化后日均100架次以上</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">高频运营，需长期规则</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">飞行高度</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">80—120米</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">低高度，仍属城市敏感低空</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">飞行区域</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">城市主干道、河道、公园上空</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">典型末端配送空域</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">避让对象</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">医院、学校、人流密集区、机场净空区</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">已做安全风险规避</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">批复主体</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">西部战区空军某部航管处</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">涉及军方空域许可</td></tr></tbody></table></div><hr style=\"border:none;border-top:1px solid #E3E8F0;margin:18px 0;\"><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">二、企业获批的完整链条</h2><h3 style=\"font-size:15px;font-weight:700;margin:20px 0 8px;color:#1E3A5F;\">第一步：地方政府把项目变成\"低空经济场景\"</h3><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">空天智航是双流经开区重点招引企业，2025年8月在双流注册投运。</p><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">这不是一般招商，而是作为低空经济产业生态来培育</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">场景合法化：低空经济示范场景 + 城市末端物流创新场景 + 低空产业生态建设场景</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>这一步决定了政府愿不愿意为它协调</b></li></ul><h3 style=\"font-size:15px;font-weight:700;margin:20px 0 8px;color:#1E3A5F;\">第二步：企业+技术方完成航线技术方案</h3><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">空天智航联合丰翼科技（深圳已有日均2000+架次运营经验）。</p><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">申请材料不是普通\"飞行申请表\"，而是一套完整的方案：</p><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">三条航线坐标、起降点位置</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">航线高度层、安全缓冲区</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">航线避让说明、飞行器技术参数</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">通信链路方案、失链返航方案</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">应急迫降点/应急处置预案</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">日常运行报备制度、操控员管理制度</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">飞行频次与时间窗口安排</li></ul><h3 style=\"font-size:15px;font-weight:700;margin:20px 0 8px;color:#1E3A5F;\">第三步：核心策略——不申请\"面\"，只申请\"线\"</h3><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">✅ 不申请大面积空域，只申请3条固定航线</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">✅ 不申请自由飞，只申请固定路径</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">✅ 不申请泛商业化，只申请标准化运营</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">✅ 80-120米，沿主干道、河道、公园上空</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">✅ 避开医院、学校、人流密集区和机场净空区</li></ul><blockquote style=\"background:#EAF1FE;border-left:3px solid #2563EB;border-radius:0 10px 10px 0;padding:12px 14px;margin:14px 0;font-size:13.5px;line-height:1.8;color:#1E3A5F;\"><b>可控、可审、可监测、可复用的航线申请</b>——军方更容易接受的方式。</blockquote><h3 style=\"font-size:15px;font-weight:700;margin:20px 0 8px;color:#1E3A5F;\">第四步：军地协调链路（推测）</h3><pre style=\"background:#0F1B33;color:#D8E2F5;border-radius:12px;padding:14px;font-size:12.5px;line-height:1.7;overflow-x:auto;margin:14px 0;white-space:pre-wrap;word-break:break-word;\">双流区/双流经开区 → 成都市低空经济协调机制\n    → 省级低空协同体系或军地协调渠道\n    → 西部战区空军某部航管处\n</pre><h3 style=\"font-size:15px;font-weight:700;margin:20px 0 8px;color:#1E3A5F;\">第五步：批复内容（推测）</h3><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">哪3条航线可以飞</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">飞行高度80—120米</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">起降点位置</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">飞行器类型：ARK40</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">运行频次上限</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">飞行时间窗口</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">禁飞/停飞条件</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">数据回传要求</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">应急处置机制</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">后续飞行计划报备机制</li></ul><hr style=\"border:none;border-top:1px solid #E3E8F0;margin:18px 0;\"><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">三、政府的三个关键作用</h2><div style=\"overflow-x:auto;margin:14px 0;\"><table style=\"width:100%;border-collapse:collapse;font-size:12.5px;\"><tbody><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">作用</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">说明</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\"><b>项目正当性</b></td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">重点招引企业 → 低空产业生态一环，非单纯商业玩家</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\"><b>协调入口</b></td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">企业很难直接对接西部战区空军，需军地协调渠道</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\"><b>责任兜底</b></td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">军方最关心\"飞偏了谁负责、掉下来谁负责\"——无政府背书，企业难独立承担</td></tr></tbody></table></div><hr style=\"border:none;border-top:1px solid #E3E8F0;margin:18px 0;\"><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">四、获批核心原因：低风险可控设计</h2><div style=\"overflow-x:auto;margin:14px 0;\"><table style=\"width:100%;border-collapse:collapse;font-size:12.5px;\"><tbody><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">因素</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">详情</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">高度低</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">80-120米，远低于通航和民航主航路</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">航线短</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">11-16分钟，城区短距离闭环配送</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">避敏感区</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">沿主干道、河道、公园，避开学校医院</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">机型成熟</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">丰翼ARK40在深圳已有成熟经验</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">频次可控</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">日均100架次，深圳参考2000架次，属可控试点</td></tr></tbody></table></div><hr style=\"border:none;border-top:1px solid #E3E8F0;margin:18px 0;\"><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">五、三级组合模型</h2><pre style=\"background:#0F1B33;color:#D8E2F5;border-radius:12px;padding:14px;font-size:12.5px;line-height:1.7;overflow-x:auto;margin:14px 0;white-space:pre-wrap;word-break:break-word;\">第一层：地方政府项目背书\n    └─ 招商 + 产业生态建设 → 纳入低空经济场景\n\n第二层：固定航线批复\n    └─ 西部战区空军某部航管处 → 对3条固定航线批复\n\n第三层：日常飞行计划报备\n    └─ 航线获批后 → 按批复条件 → 平台报备 → 执行调度 → 飞后留痕\n</pre><hr style=\"border:none;border-top:1px solid #E3E8F0;margin:18px 0;\"><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">六、对成都低空经济的意义</h2><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>从验证飞行 → 常态化飞行</b></li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">之前更多是干线验证、场景展示，这次明确\"常态化低空城市物流航线\"</li></ul><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>从外围空域 → 五城区末端配送</b></li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">不再是淮州、崇州、自贡等外围，开始碰城市核心配送网络</li></ul><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>从单次审批 → 固定航线+标准监管</b></li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">为成都低空物流常态化空域使用打造\"可复制、可推广的审批范本\"</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">推动\"固定航线+常态化飞行+标准化监管\"模式落地</li></ul><hr style=\"border:none;border-top:1px solid #E3E8F0;margin:18px 0;\"><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">七、最终判断</h2><blockquote style=\"background:#EAF1FE;border-left:3px solid #2563EB;border-radius:0 10px 10px 0;padding:12px 14px;margin:14px 0;font-size:13.5px;line-height:1.8;color:#1E3A5F;\"><b>这不是企业单独申请成功，而是\"政府产业场景 + 企业技术方案 + 军方安全批复 + 平台化监管\"共同跑通。</b></blockquote><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">对低空咨询的启发：</p><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">真正有价值的不是帮企业\"写一份空域申请\"</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">而是帮企业把一个商业需求，改造成<b>军方愿意批、政府愿意背书、平台能够监管</b>的\"固定航线产品\"</li></ul><hr style=\"border:none;border-top:1px solid #E3E8F0;margin:18px 0;\"><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">*分析来源：ChatGPT 深度分析 | 归档：Codex → Obsidian*</p><hr style=\"border:none;border-top:1px solid #E3E8F0;margin:18px 0;\"><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">总库：徐总的知识库</p>","低空经济/成都首条常态化低空城市物流航线.md":"<h1 style=\"font-size:19px;font-weight:800;margin:18px 0 10px;color:#16233B;\">双流企业领飞！成都首条常态化低空城市物流航线正式开通</h1><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\"><b>来源：</b> 中国网 | <b>日期：</b> 2026-05-23</p><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\"><b>原文：</b> [http://photo.china.com.cn/2026-05/23/content_118510469.shtml](http://photo.china.com.cn/2026-05/23/content_118510469.shtml)</p><hr style=\"border:none;border-top:1px solid #E3E8F0;margin:18px 0;\"><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\"><b>tags:</b> 低空经济, 成都, 双流, 无人机物流, ARK40, 空天智航, 丰翼科技</p><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">1. 核心事件</h2><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">5月22日，成都首条常态化低空城市物流航线正式开通。4架中型八旋翼物流无人机从卡丁车公园起降点起飞，标志着成都低空物流进入常态化运营阶段。</p><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">2. 运营主体</h2><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>空天智航</b>（四川空天智航科技有限公司）— 双流区重点招引企业，低空经济产业生态集成服务商</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">主营：低空+物流、文旅、巡检、消防等</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">提供：空域规划、航线设计、执照培训等服务</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">2025年8月在双流注册投运</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>丰翼科技</b>（深圳）有限公司 — 无人机研发与制造</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">首期开通 3 条固定低空城市物流航线</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">计划 2026年6月进入常态化运行</li></ul><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">3. 技术参数</h2><div style=\"overflow-x:auto;margin:14px 0;\"><table style=\"width:100%;border-collapse:collapse;font-size:12.5px;\"><tbody><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">指标</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">数据</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">无人机型号</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">ARK40 中型八旋翼物流无人机</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">额定载重</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">10 公斤</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">续航</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">20 公里</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">飞行模式</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">80-120 米低空贴城飞行</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">航线时长</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">11-16 分钟</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">日均架次</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">首日50架次，常态化后 100 架次以上</td></tr></tbody></table></div><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">4. 空域审批深度分析</h2><h3 style=\"font-size:15px;font-weight:700;margin:20px 0 8px;color:#1E3A5F;\">4.1 审批层级与流程</h3><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\"><b>审批机构：</b> 西部战区空军某部航管处</p><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">说明成都低空航线审批需经<b>战区级空军航管部门</b>批准，非市级或省级层面可以独立决定</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">涉及城市人口密集区的低空航线，安全审查标准更为严格</li></ul><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\"><b>审批流程（原文披露）：</b></p><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>飞行计划申请报备流程</b> — 每次飞行前需按流程申报</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>飞行操控程序</b> — 有标准化操控流程</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>安全管理方案</b> — 需提交安全评估文件</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>应急处置预案</b> — 包含应急响应机制</li></ul><h3 style=\"font-size:15px;font-weight:700;margin:20px 0 8px;color:#1E3A5F;\">4.2 空域规划方法论</h3><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">空天智航总经理刘哲瑞透露的关键设计原则：</p><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\"><b>航线选取原则：</b></p><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">主要选取城市主干道、河道及公园上空</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">采用 80-120 米低空贴城飞行模式</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">严格避开医院、学校等核心密集区</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">避开机场净空区</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">网格化、短距离闭环设计</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">精准适配主城区高频小件即时配送需求</li></ul><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\"><b>勘测工作：</b> 空天智航团队进行了大量实地勘测与规划</p><h3 style=\"font-size:15px;font-weight:700;margin:20px 0 8px;color:#1E3A5F;\">4.3 审批模式价值</h3><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">为成都低空物流的常态化空域使用提供<b>可复制、可推广的审批范例</b></li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">推动 <b>\"固定航线 + 常态化飞行 + 标准化监管\"</b> 机制成型</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">对后续其他城市 / 其他企业的低空航线审批具有参考意义</li></ul><h3 style=\"font-size:15px;font-weight:700;margin:20px 0 8px;color:#1E3A5F;\">4.4 法规制度背景（推测）</h3><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">基于公开信息，推测该审批涉及以下法规框架：</p><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">《无人驾驶航空器飞行管理暂行条例》</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">空军低空空域管理规定</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">成都市低空经济相关地方政策</li></ul><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">5. 时效与效率</h2><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">航线开通首日计划飞行 50 个架次</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">常态化运营后日均可达 100 架次以上</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">相较于传统运输方式，平均时限提升 2-3 倍</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">综合评估性价比提升一倍</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">深圳已有成熟运营经验（每日 2,000+ 架次）</li></ul><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">6. 安全措施</h2><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">规避因多次转运、路面颠簸及磕碰带来的货损</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">航线严格避开高风险区域</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">有标准化飞控程序与应急预案</li></ul><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">7. 产业生态</h2><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">双流已集聚追梦空天、松正航空动力、华体科技、捌三肆一等低空重点企业，覆盖整机制造、反制系统、飞手培训等领域。</p><hr style=\"border:none;border-top:1px solid #E3E8F0;margin:18px 0;\"><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">后续关注方向</h2><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">常态化运行后的实际审批流程细节</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">其他城市是否复制此审批范例</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">空域申请的标准流程是否逐步公开</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">低空经济法规的进一步完善</li></ul><hr style=\"border:none;border-top:1px solid #E3E8F0;margin:18px 0;\"><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">*笔记来源：Codex 自动抓取归档 | 2026-05-26*</p><hr style=\"border:none;border-top:1px solid #E3E8F0;margin:18px 0;\"><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">总库：徐总的知识库</p>","低空经济/空天智航与丰翼合作模式分析.md":"<h1 style=\"font-size:19px;font-weight:800;margin:18px 0 10px;color:#16233B;\">空天智航与丰翼合作模式分析——联合体模式的审批逻辑</h1><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\"><b>归档日期：</b> 2026-05-26</p><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\"><b>关联笔记：</b> 成都首条常态化低空城市物流航线, 成都双流低空物流航线空域审批深度分析</p><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\"><b>tags:</b> 空天智航, 丰翼, 联合体, 属地责任, 责任共同体, 合作模式, 顺丰, 深圳, 咨询方法论</p><hr style=\"border:none;border-top:1px solid #E3E8F0;margin:18px 0;\"><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">核心判断</h2><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">你的判断很有可能接近真实分工，但\"空天智航是不是壳\"这个说法要分开看：</p><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">如果\"壳\"指没有实际价值、只是挂名，那未必准确</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">如果指本地平台型主体、资源接口和牌照承接主体，那这个判断是成立的</li></ul><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">这次更像是：<b>丰翼提供成熟无人机物流运营能力，空天智航提供成都本地化落地载体与政府/空域协同接口。</b></p><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">不是简单谁替谁，而是<b>深圳成熟运营商 + 成都本地平台公司</b>的组合。</p><hr style=\"border:none;border-top:1px solid #E3E8F0;margin:18px 0;\"><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">一、为什么\"专业运营主要是丰翼\"是合理的</h2><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">从公开信息看，首批投放的是丰翼自主研发的 ARK40 中型八旋翼物流无人机，额定载重10公斤、续航20公里；丰翼副总裁也在报道中介绍了无人机配送效率，并提到该型号已在深圳常态化运营、每日飞行超过2000架次。</p><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">这说明几个问题：</p><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>机型是丰翼的</b>——ARK40不是空天智航自研，而是丰翼成熟产品</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>运营经验是丰翼的</b>——深圳每日2000架次以上的运行经验，是审批时最有说服力的安全样本</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>飞控、调度、运行规程大概率是丰翼体系输出</b>——城市道路、楼宇间、80-120米低空飞行，关键是成熟的航线运行SOP、飞行报备、数据回传、应急处置、机队维护和远程调度</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>军方/监管最看重的\"已验证运行能力\"，主要来自丰翼</b>——对西部战区空军航管处来说，一个已经在深圳大规模运行的系统，比一个刚注册不久的本地公司更有可信度</li></ul><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">所以\"专业申请材料、飞行运营、安全流程、机型支撑大概率主要来自丰翼\"这个判断是合理的。</p><hr style=\"border:none;border-top:1px solid #E3E8F0;margin:18px 0;\"><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">二、空天智航的价值：本地化承接</h2><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">空天智航公开定位是\"低空经济产业生态集成服务企业\"，业务覆盖低空物流、文旅、巡检、消防，同时提供空域规划、航线设计、执照培训等服务；并且由成都双流经开区管委会重点招引，2025年8月在双流注册投运。</p><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">几个关键词很关键：\"生态集成服务\"、\"双流经开区重点招引\"、\"在双流注册投运\"、\"提供空域规划、航线设计、执照培训\"。</p><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">这类企业通常不是单纯飞行器制造商，也未必是成熟无人机运营商，而更像：<b>地方低空经济项目承接平台 + 场景整合公司 + 政府接口公司 + 本地运营主体。</b></p><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">它的价值可能在于：</p><div style=\"overflow-x:auto;margin:14px 0;\"><table style=\"width:100%;border-collapse:collapse;font-size:12.5px;\"><tbody><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">职能</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">说明</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">承接低空产业场景</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">政府不可能直接让外地企业完全主导本地示范项目，需要本地注册主体</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">对接本地资源</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">政府、园区、起降点、物业、道路、公安、应急等</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">申请主体</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">对军方和地方来说，本地注册企业更便于监管、问责和后续产业沉淀</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">本地化包装</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">把丰翼能力包装为双流低空经济成果，对招商、产业链、示范宣传都重要</td></tr></tbody></table></div><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">所以空天智航未必是\"空壳\"，但很可能是<b>地方资源型、集成型、场景运营型公司</b>，而不是底层技术能力的主要来源。</p><hr style=\"border:none;border-top:1px solid #E3E8F0;margin:18px 0;\"><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">三、为什么不能简单说\"空天智航只是壳\"</h2><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">公开报道中写的是\"由四川空天智航科技有限公司联合丰翼科技共同推出\"，且空天智航被称为该项目运营主体或本地低空经济产业生态集成服务企业。</p><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">它至少承担了这些正式角色：</p><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">项目主体</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">本地运营承接</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">政府招商落地主体</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">可能的空域/航线本地申报配合主体</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">后续本地业务拓展主体</li></ul><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">如果说\"它只是壳\"，容易低估它在本地化合法性和政府协同中的作用。更准确的说法是：</p><blockquote style=\"background:#EAF1FE;border-left:3px solid #2563EB;border-radius:0 10px 10px 0;padding:12px 14px;margin:14px 0;font-size:13.5px;line-height:1.8;color:#1E3A5F;\"><b>丰翼是能力输出方，空天智航是本地承接方；丰翼解决'怎么飞'，空天智航解决'在成都以什么身份、通过什么本地关系和场景飞'。</b></blockquote><hr style=\"border:none;border-top:1px solid #E3E8F0;margin:18px 0;\"><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">四、这类组合在低空经济里为什么很常见</h2><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">低空经济项目有一个特点：技术公司单独进入地方，往往飞不起来；地方平台单独干，又没有成熟能力。</p><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">最常见的组合就是：</p><div style=\"overflow-x:auto;margin:14px 0;\"><table style=\"width:100%;border-collapse:collapse;font-size:12.5px;\"><tbody><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">角色</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">作用</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">外部成熟运营商</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">机型、飞控、调度、SOP、安全案例</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">本地注册/平台公司</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">政府关系、场景资源、牌照承接、地方责任</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">区县政府/园区</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">招商背书、场地协调、产业政策、军地协同入口</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">军方航管部门</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">批复固定航线和运行边界</td></tr></tbody></table></div><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">这次双流-丰翼组合，非常符合这个结构。</p><hr style=\"border:none;border-top:1px solid #E3E8F0;margin:18px 0;\"><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">五、从空域申请角度看，谁的作用更关键？</h2><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">要分环节看。</p><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\"><b>技术论证环节：丰翼更关键。</b> 军方最关心的是安全运行能力，丰翼有深圳高频运行经验，有成熟机型和运行数据。</p><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\"><b>地方协调环节：空天智航更关键。</b> 项目要变成\"双流企业领飞\"\"双流低空经济生态成果\"，就需要本地企业承接。</p><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\"><b>批复说服环节：两者缺一不可。</b></p><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">只有空天智航，没有丰翼：缺成熟运行能力，军方安全信任不足</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">只有丰翼，没有空天智航：缺成都本地化抓手，地方政府招商和监管承接不足</li></ul><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">真实结构大概率是：<b>丰翼提供可信运行能力，空天智航提供地方承载结构，双流政府提供场景和协调背书。</b></p><hr style=\"border:none;border-top:1px solid #E3E8F0;margin:18px 0;\"><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">六、军方认可的逻辑：四个条件</h2><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">军方审批看的不是\"谁有什么\"，而是\"这个飞行活动是否安全可控、责任主体是否明确\"。</p><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">空天智航需要提供的是<b>法律层面的责任主体证明</b>（营业执照），而安全运营的技术能力证明则由丰翼提供，双方通过协议形成一个权责清晰的<b>\"责任共同体\"</b>。</p><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">军方认可的关键证据：</p><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\"><b>1. 媒体报道直接证实。</b> 多家权威媒体报道这次航线\"已获西部战区空军某部航管处批复\"。空天智航是\"运营主体\"，丰翼是\"携手\"的合作伙伴。</p><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\"><b>2. 官方分工清晰。</b> 空天智航负责\"实地勘测与规划\"，在空中\"选取城市主干道、河道及公园上空\"，并\"制定了严格的飞行计划申请报备流程、飞行操控程序，以及安全管理方案与应急处置预案\"。丰翼负责提供ARK40，并基于深圳成熟经验提供技术支撑。</p><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\"><b>3. 四川军地协同的\"放管服\"改革提供了制度基础。</b> 2018年四川试点时就明确了\"地方政府统筹低空空域需求规划，军民航按程序审批，地方政府负责运行管理\"，确立了\"军地民\"协同管理模式。这套流程完全在这个框架内运行。</p><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\"><b>4. 责任归属是审批核心。</b> 军方最关心的是\"如果出事，谁负责？\"联合运营协议明确了双方分工——空天智航是政府招引企业，承担对外法律责任；丰翼是技术和运营的实际执行方。协议摆在审批部门案头，就形成了一个权责清晰的\"责任共同体\"。</p><hr style=\"border:none;border-top:1px solid #E3E8F0;margin:18px 0;\"><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">七、审批材料构成（推测）</h2><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">按固定航线批复逻辑，材料大概包括四组：</p><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\"><b>1. 主体与协议材料</b></p><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">空天智航营业执照、经营范围</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">双方合作协议或联合运营协议</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">丰翼技术服务/设备提供/运维支持说明</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">责任划分文件、保险或责任保障材料</li></ul><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\"><b>2. 航线技术材料</b></p><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">3条航线坐标、起降点坐标</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">航线高度80-120米、路径选择依据</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">避让医院、学校、人流密集区、机场净空区说明</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">航线缓冲区或电子围栏设计</li></ul><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\"><b>3. 机型与运行材料</b></p><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">ARK40性能参数、载重、续航、通信链路</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">飞控/定位/数据回传能力</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">操控员/运维人员管理</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">深圳常态化运行案例或安全记录</li></ul><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\"><b>4. 安全管理材料</b></p><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">飞行报备流程、起飞前检查流程</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">失链返航/备降/迫降预案</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">超高/偏航/禁飞触发机制</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">应急处置预案</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">飞行记录与监管数据留存方案</li></ul><hr style=\"border:none;border-top:1px solid #E3E8F0;margin:18px 0;\"><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">八、对低空咨询的启示</h2><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">这个案例说明，真正能打通空域和航线的，不是单一能力，而是一个组合设计：</p><blockquote style=\"background:#EAF1FE;border-left:3px solid #2563EB;border-radius:0 10px 10px 0;padding:12px 14px;margin:14px 0;font-size:13.5px;line-height:1.8;color:#1E3A5F;\"><b>本地平台公司 + 成熟运营商 + 政府场景背书 + 固定航线技术方案 + 军方批复 + 后续平台化报备</b></blockquote><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">咨询公司的价值不是\"写空域申请\"，而是帮客户完成这几个结构设计：</p><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">找到本地责任主体</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">找到成熟技术运营方</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">把商业配送包装成地方低空经济示范场景</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">把自由飞行需求压缩成固定航线产品</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">把风险责任拆分到协议和技术方案里</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">让军方看到\"可控、可叫停、可追责\"</li></ul><hr style=\"border:none;border-top:1px solid #E3E8F0;margin:18px 0;\"><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">最终判断</h2><blockquote style=\"background:#EAF1FE;border-left:3px solid #2563EB;border-radius:0 10px 10px 0;padding:12px 14px;margin:14px 0;font-size:13.5px;line-height:1.8;color:#1E3A5F;\"><b>军方认可的不是空天智航单独的技术能力，而是认可\"空天智航作为本地运营责任主体 + 丰翼作为成熟技术运营方 + 双流政府场景背书 + 固定航线安全方案\"所形成的责任共同体。</b></blockquote><blockquote style=\"background:#EAF1FE;border-left:3px solid #2563EB;border-radius:0 10px 10px 0;padding:12px 14px;margin:14px 0;font-size:13.5px;line-height:1.8;color:#1E3A5F;\"></blockquote><blockquote style=\"background:#EAF1FE;border-left:3px solid #2563EB;border-radius:0 10px 10px 0;padding:12px 14px;margin:14px 0;font-size:13.5px;line-height:1.8;color:#1E3A5F;\">这就是当前低空物流城市航线能获批的核心模式。</blockquote><hr style=\"border:none;border-top:1px solid #E3E8F0;margin:18px 0;\"><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">*归档方式：原文保留 + 结构组织 | 原始对话归档*</p><hr style=\"border:none;border-top:1px solid #E3E8F0;margin:18px 0;\"><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">总库：徐总的知识库</p>","低空经济/蜀道集团低空经济：无人机巡检·招投标采购与产业协作体系.md":"<h1 style=\"font-size:19px;font-weight:800;margin:18px 0 10px;color:#16233B;\">蜀道集团低空经济：无人机巡检·招投标采购与产业协作体系</h1><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\"><b>归档/合并日期：</b> 2026-08-20（由「蜀道集团大疆无人机巡检方案与算法架构」+「蜀道集团低空经济产业协作单位资源库」合并）</p><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\"><b>关联笔记：</b> 低空经济专题、空天智航与丰翼合作模式分析（同为\"联合体/合作网络\"模式）、蜀道集团大疆无人机巡检：采购投资与融资租赁测算（财务层·另文）、蜀道集团研究线（蜀道主体聚合入口）</p><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\"><b>tags:</b> 蜀道集团, 蜀交低空, 大疆, 无人机巡检, 蜀道智巡, 低空经济, 算法分层, 适配版, 协作单位资源库, 招投标, 采购, 供应商入库, 通用机场, 空域研究, 联合体, 马边彝族自治县</p><hr style=\"border:none;border-top:1px solid #E3E8F0;margin:18px 0;\"><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">本笔记把蜀道集团（省属国企）体系下「四川蜀交低空经济产业发展有限公司」（蜀交低空公司）的低空经济动作，按 <b>上游基础设施/空域层（马边通用机场选址 + 低空空域研究）→ 技术层（无人机巡检/蜀道智巡）→ 招投标采购层（江油市项目 + 协作单位资源库）→ 生态/平台化解读</b> 四层合为一册，避免同一主体散在多篇。蜀交低空是蜀道低空经济的平台型主体，自研「蜀道智巡」系统，2025-12 起连续从最上游（空域/机场）到最下游（无人机采购落地）全线布局，标志其从单套巡检系统走向平台型生态。</p><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">一、主体与定位</h2><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>四川蜀交低空经济产业发展有限公司（蜀交低空公司）</b>：蜀道集团体系下的低空经济平台型主体；</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">蜀道交通服务集团\"低空+交通服务多场景应用\"<b>获批四川省首批低空经济试点</b>；</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">自研 <b>「蜀道智巡」系统</b>（业务智巡层核心）；</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>全价值链布局（2025-12 起）：</b> ① <b>上游</b>——以联合体成员身份中标马边彝族自治县通用机场（含起降点）选址论证及低空经济应用试点空域研究服务（2025-12-23 成交）；② <b>中游</b>——低空经济产业协作单位资源库公开遴选（2026-01-05）；③ <b>下游</b>——江油市低空经济\"先行先试\"项目无人机及配套设施采购中标候选公示（2026-01-19）。</li></ul><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">二、无人机巡检方案与算法架构（技术层）</h2><h3 style=\"font-size:15px;font-weight:700;margin:20px 0 8px;color:#1E3A5F;\">2.1 采购事实（已核实，非猜测）</h3><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">2025 年启动无人机智能化巡检，部署 <b>大疆机场 3（DJI Dock 3）+ Matrice 4TD + 蜀道自研\"蜀道智巡\"系统</b>；</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">\"蜀道智巡\"明确写\"<b>兼容大疆机场 3、M400 等无人机</b>\"，可智能识别路面裂缝、山体滑坡、设施异常等 <b>20+ 类问题，准确率&gt;90%</b>；</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">应用场景：高速边坡/桥梁巡检、应急车道违停驱离、施工期安全巡检（安全帽/反光衣识别）等。</li></ul><h3 style=\"font-size:15px;font-weight:700;margin:20px 0 8px;color:#1E3A5F;\">2.2 为什么选大疆（不止\"品牌\"）</h3><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">真实根因三层叠加：① 飞行平台成熟（RTK、六向避障、自主机场、恶劣环境冗余）；② <b>生态最开放</b>（SDK 注册开发者超 10 万、MSDK 应用 1000+、PSDK 负载 200+，决定\"能否被快速适配\"）；③ 央企/省属国企采购逻辑（合规、售后、培训、数据安全本地部署）。</p><h3 style=\"font-size:15px;font-weight:700;margin:20px 0 8px;color:#1E3A5F;\">2.3 系统架构（三层）</h3><div style=\"overflow-x:auto;margin:14px 0;\"><table style=\"width:100%;border-collapse:collapse;font-size:12.5px;\"><tbody><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">层</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">负责方</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">职责</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\"><b>硬件层</b></td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">大疆（机场 3 / M4TD / M400）</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">飞行、采数据、推直播流、自主起降充电</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\"><b>飞控 + 实时算法层</b></td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\"><b>凌次方飞控平台</b>（第三方·山东天和翔通旗下品牌）</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">机队/多机场管理、航线分发、接直播流做<b>实时 AI</b>、视频落盘</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\"><b>业务智巡层</b></td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\"><b>蜀道智巡</b>（蜀交低空公司自研）</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\"><b>深度识别</b>（20+ 类缺陷）、多源融合、数字孪生、告警→工单→闭环</td></tr></tbody></table></div><blockquote style=\"background:#EAF1FE;border-left:3px solid #2563EB;border-radius:0 10px 10px 0;padding:12px 14px;margin:14px 0;font-size:13.5px;line-height:1.8;color:#1E3A5F;\">注：「凌次方」常被语音误读为\"零次方\"，本文统一用「凌次方」。</blockquote><h3 style=\"font-size:15px;font-weight:700;margin:20px 0 8px;color:#1E3A5F;\">2.4 直播流与数据链路</h3><pre style=\"background:#0F1B33;color:#D8E2F5;border-radius:12px;padding:14px;font-size:12.5px;line-height:1.7;overflow-x:auto;margin:14px 0;white-space:pre-wrap;word-break:break-word;\">无人机（大疆机载图传 O4 Enterprise）\n → 大疆机场3 / 遥控器（RC Plus）\n   → 通过 DJI Cloud API 把直播流推到云平台\n     → 凌次方平台（接流 + 实时分析 + 视频存储）\n       → 蜀道智巡（深度识别 + 融合边坡位移传感 + 数字孪生 → 工单闭环）\n</pre><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">大疆负责\"产生 + 推送\"直播流（传输层），接收/分析端是上层平台。</p><h3 style=\"font-size:15px;font-weight:700;margin:20px 0 8px;color:#1E3A5F;\">2.5 算法分工（核心）</h3><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>飞行级 AI（大疆自己的，行业最强）</b>：避障、RTK 定位、自主起降充电、AI Spot-Check 自动取景；</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>场景级 AI（不是大疆通用的，是适配版的）</b>：</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">凌次方（实时）：应急车道停车、车流统计、行人闯入、烟火监测；</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">蜀道智巡（深度）：裂缝、滑坡、设施异常等 20+ 类、准确率 &gt;90%；</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>大疆真正提供的</b>：视频源 + 算力底座（Edge SDK / Manifold 3 边缘计算）+ 数据通道（Cloud API）。道路勘察的识别模型，大疆通用版里没有，是适配层自训的。</li></ul><h3 style=\"font-size:15px;font-weight:700;margin:20px 0 8px;color:#1E3A5F;\">2.6 通用版 vs 适配版</h3><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>通用版</b>（DJI Pilot / Terra / FlightHub / Dock）：飞行、建模、机队、自主机场——成熟，但<b>不自带高速缺陷识别</b>；</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>适配版</b>（凌次方 / 蜀道智巡）：建在 DJI SDK / Cloud API / Edge SDK 之上，跑自训模型；</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">\"通用版已建好高速场景\"——准确说是\"<b>生态/伙伴层已有适配包</b>，不是大疆自带\"。</li></ul><h3 style=\"font-size:15px;font-weight:700;margin:20px 0 8px;color:#1E3A5F;\">2.7 所有权纠偏</h3><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>蜀道智巡 = 蜀道自研</b> ✅（蜀交低空公司自主研发，官方稿佐证）；</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>凌次方飞控平台 = 第三方</b>（山东天和翔通旗下品牌），蜀道是\"<b>引入/采用</b>\"，<b>不是蜀道自研</b>（报道把\"大疆机场3、Matrice 4TD 飞行器<b>与</b>凌次方飞控平台\"并列\"引入\"，说明它是被采用的外部平台）。</li></ul><h3 style=\"font-size:15px;font-weight:700;margin:20px 0 8px;color:#1E3A5F;\">2.8 一句话结论（技术层）</h3><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\"><b>蜀道买的是大疆\"靠谱飞行平台 + 好适配的底座\"；场景智能（实时看异常 + 深度识缺陷 + 业务闭环）是凌次方（第三方飞控）和蜀道智巡（蜀道自研）在适配层搭的。大疆 = 手和眼睛，凌次方 = 现场调度 + 实时判，蜀道智巡 = 大脑 + 闭环。</b></p><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">三、招投标与采购事件（招投标/采购层）</h2><h3 style=\"font-size:15px;font-weight:700;margin:20px 0 8px;color:#1E3A5F;\">3.1 江油市低空经济\"先行先试\"项目无人机及配套设施采购（中标候选人公示）</h3><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>招标人：</b> 四川蜀交低空经济产业发展有限公司</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>公示发布：</b> 2026-01-19；<b>公示期限：</b> 发布之日起至 <b>2026-01-22</b></li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>中标候选人：</b></li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">第一中标候选人：成都北斗众联科技有限公司</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">第二中标候选人：成都特旺科技有限责任公司</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">第三中标候选人：四川徕拓科技发展有限公司</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>采购内容：</b> 无人机及配套设施</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>异议联系方式：</b> 13558580099</li></ul><h3 style=\"font-size:15px;font-weight:700;margin:20px 0 8px;color:#1E3A5F;\">3.2 低空经济产业协作单位资源库（公开遴选）</h3><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>公告日期：</b> 2026-01-05；<b>申请文件递交截止：</b> 2026-01-15 14:30（成都市锦江区三色路163号银海芯座B座16楼）</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>性质：</b> 公开遴选\"协作单位资源库\"（供应商/合作单位入库），非单笔采购</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>协作服务内容（三大类）：</b></li><div style=\"overflow-x:auto;margin:14px 0;\"><table style=\"width:100%;border-collapse:collapse;font-size:12.5px;\"><tbody><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">类别</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">覆盖单位</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">研发制造类</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">低空经济涉及的研发、设计及装备制造单位</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">规划建设类</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">低空经济基础设施的规划设计建造；相关<b>通导监</b>（通信/导航/监视）设施设备供应单位</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">运营类</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">交通巡查巡检、应急消防救援、城乡综合治理、文旅研学培训等（细项含低空旅游、热气球/滑翔伞/动力伞、飞行俱乐部、航空营地、无人机灯光秀、有/无人机执照培训·考试·赛事、航空科普、游学研学、通用航空服务、民用航空器维修、智能无人飞行器销售、应急救援、环境监测、农作物病虫害防治等）</td></tr></tbody></table></div><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>申请人资格门槛：</b> 独立法人、商业信誉与健全财务、履约能力、纳税社保良好、近 3 年无重大违法；具备服务内容相关资质 + <b>有效安全生产许可证</b>；<b>2024-01-01 至今具有 3 个金额不少于 20 万元的相关工程/订单/科研课题合同</b>；进入退出机制参照公司管理办法。</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>联系人：</b> 邱先生 13880519027、常先生 13708029603</li></ul><h3 style=\"font-size:15px;font-weight:700;margin:20px 0 8px;color:#1E3A5F;\">3.3 两件事的关系</h3><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">时间都集中在 <b>2026-01</b>、同一主体（蜀交低空公司）；</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>资源库 = \"入库建池\"</b>（搭建合作网络），<b>江油市项目 = \"发包采购\"</b>（网络里第一个落地的具体采购标的）；</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">运营类清单明确含\"交通巡查巡检\"，与蜀道智巡主场景重合——资源库为江油市这类项目输送装备商/运营方；</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>待核实：</b> 江油市采购中标候选人（北斗众联/特旺科技/徕拓科技）是否已进入或拟进入资源库，二者是否为同一批合作方脉络。</li></ul><h3 style=\"font-size:15px;font-weight:700;margin:20px 0 8px;color:#1E3A5F;\">3.4 马边彝族自治县通用机场（含起降点）选址论证及低空经济应用试点空域研究服务项目（联合体中标）</h3><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>来源：</b> 四川政府采购网；<b>发布时间：</b> 2025-12-23 14:20:54；<b>项目编号：</b> N5111332025000138</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>采购人：</b> 马边彝族自治县发展和改革局</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>中标（成交）供应商（联合体）：</b> 民航机场建设集团西南设计研究院有限公司（联合体成员：<b>四川蜀交低空经济产业发展有限公司</b>）</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>中标金额：</b> 1,589,800.00 元；<b>评审总得分：</b> 97.50</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>服务内容（合同包1，品目 C20039900 其他咨询服务）：</b></li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">低空经济应用试点空域研究服务：自合同签订之日起 <b>50 日内</b>完成；</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">通用机场（含起降点）选址服务：自合同签订之日起 <b>120 日内</b>完成；</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>代理服务费：</b> 按成交金额 2.5% 收取，3.9745 万元，由中标（成交）供应商支付。</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>意义：</b> 蜀交低空<b>首次以\"联合体成员\"身份进入通用机场选址 + 低空空域研究这一最上游环节</b>——此前其动作均集中在\"用无人机\"（巡检/智巡系统）和\"建合作池\"（资源库），本事件标志其向基础设施与空域资源（低空经济真正稀缺的准入门槛）上游延伸。</li></ul><h3 style=\"font-size:15px;font-weight:700;margin:20px 0 8px;color:#1E3A5F;\">3.5 蜀交低空为何参与此项目（研判）</h3><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>卡位最稀缺资源——空域与起降点。</b> 此前蜀交低空的动作（巡检/智巡、资源库、江油采购）都在\"用无人机\"和\"搭合作网络\"；而通用机场选址 + 低空空域研究是低空经济真正的准入门槛。谁为县域做空域研究，谁就实质上参与该辖区低空可飞区/航线的规则制定。蜀交低空借此从\"应用方\"升级为\"基础设施与空域的编排方\"。</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>以联合体补资质短板。</b> 机场选址论证需民航专业资质，蜀交低空本身不具备；拉民航机场建设集团西南设计研究院（民航系统下属设计院）作牵头方、自己作成员，用\"地方国企政治资本 + 低空应用场景经验（蜀道智巡/无人机运营）+ 联合体身份\"换取进入基础设施层的门票。</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>从\"高速走廊\"扩展到\"县域低空\"。</b> 蜀道智巡原主战场是高速公路巡检；马边彝族自治县是乐山下辖县，本项目把蜀交低空的能力边界从\"路\"推到\"县域通用机场 + 低空应用试点\"，等于把其运营能力包装成\"试点空域的应用运营商\"候选。</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>抢占县域低空经济\"首进\"关系。</b> 县域是低空经济应用试点下沉的单元，马边属需做出低空经济成绩的欠发达县，预算与政绩诉求并存。蜀交低空以联合体成员身份被写入县域低空经济基础规划，等于锁定了后续机场建成后的运营/应用合作先机。</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>与资源库、江油采购构成完整链条，印证\"平台化\"主线。</b> 上游（空域/机场研究）→ 中游（合作池/资源库）→ 下游（江油无人机采购落地）三层全部就位，蜀交低空在蜀道体系内从\"买无人机的部门\"变成\"低空经济全栈编排者\"。</li></ul><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">四、生态/平台化解读</h2><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">蜀交低空在蜀道智巡（自研系统）跑通后，用<b>入库机制</b>把上下游（装备商、通导监供应商、运营服务商）收编进自己的低空经济版图，与 空天智航与丰翼合作模式分析 的\"联合体\"逻辑同源，只是蜀道是<b>省属国企自上而下的平台化</b>路径；</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">\"通导监设施设备供应\"被单列，暗示蜀道低空后续可能自建有/无人体低空监视与通信底座，值得跟踪。</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>马边事件是平台化最有力的证据，且把战线推到了最上游。</b> 此前\"资源库入库 + 江油采购\"还停留在\"用无人机 / 搭合作网络\"；而通用机场选址 + 低空空域研究是低空经济真正的准入门槛与稀缺资源。蜀交低空以联合体成员身份切入这一最上游环节，等于从\"应用方\"升级为\"基础设施与空域的编排方\"——上游（空域/机场研究）→ 中游（合作池/资源库）→ 下游（江油无人机采购落地）三层全部就位，蜀交低空在蜀道体系内已从\"买无人机的部门\"变成\"低空经济全栈编排者\"。其参与的现实抓手是：借民航设计院资质补自身短板，用地方国企政治资本 + 蜀道智巡的无人机运营经验换取进入基础设施层的门票，并提前锁定县域低空经济\"首进\"合作关系。</li></ul><h3 style=\"font-size:15px;font-weight:700;margin:20px 0 8px;color:#1E3A5F;\">4.1 用户战略研判：空域审批链才是真正壁垒，马边的价值在\"走通流程\"而非项目费</h3><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>最基础的基础设施 = 必须真实跑通一条跨军地的空域审批链。</b> 通用机场选址 + 低空空域研究之所以是最底层基建，是因为它要对接：县域低空经济试点 → 县政府 → <b>省发改委 / 省政府</b>（国家鼓励低空经济基础设施修建）→ <b>西部战区（空域实际由战区军事管辖）与民航对空域的划分协调</b>。其中\"西部战区\"这一环是低空经济最难啃的部分——<b>空域使用权在军队，不在地方政府</b>，能把可飞区/航线与战区对接落定，才是真正稀缺的能力。</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>马边项目的战略价值不在 159 万，而在\"至少走了这个流程\"。</b> 若蜀交低空借这个县域试点被写进该审批链、并跑通与西部战区 + 民航 + 省政府的协同流程，等于沉淀下一套\"可复制的空域打通方法论\"，其价值远超任何单笔项目费。</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>\"县域切入、向上打通\"路径（用户判断）：</b> 先用一个县把县政府关系与基础流程占住，再依托蜀道（省属国企）身份向上推到省级乃至军地协同。这套打法如果能打通，是\"非常大的值得弄的事\"。</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>用户审慎态度（明确标注）：</b> 不清楚蜀交低空公司自身的人脉与能力是否撑得住这条链；但判断\"这个事情不是那么简单\"——能否真正打通西部战区与政府的流程，是该项目成败与可复制性的关键未知项，需持续跟踪验证。</li></ul><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">五、采购投资与融资租赁（财务层，另文）</h2><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">大疆机场3 采购的财务测算详见 蜀道集团大疆无人机巡检：采购投资与融资租赁测算：NPV 三方案对比（自购 +59.1 万 / 融资租赁 +67.8 万 / 维持人工 -102.3 万）、盈亏平衡 8.8 万/年、融资租赁产权与分期解读；iMA 金融视角内容待凭证刷新后补充。</li></ul><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">六、前提与可追问点</h2><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">资源库是\"遴选入库\"而非直接发包，入库单位后续如何被实际调用（是否绑定具体项目、有无优先采购）未见细则；</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">江油市采购与资源库是否同一批合作方脉络，待核实；</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">马边县项目中蜀交低空作为\"联合体成员\"的具体分工与收益模式（是否仅出方案/地方协调，还是后续运营绑定）未见细则；民航机场建设集团西南设计研究院与蜀交低空的权责划分值得跟踪；</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">仅买大疆通用版、不建适配版，拿不到 90% 高速巡检识别率；即便采现成适配包，落地仍需按蜀道资产定制（资产目录、历史数据降误报、对接边坡位移/数字孪生、验收阈值）。</li></ul><hr style=\"border:none;border-top:1px solid #E3E8F0;margin:18px 0;\"><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">总库：徐总的知识库</p>","低空经济/蜀道集团大疆无人机巡检：采购投资与融资租赁测算.md":"<h1 style=\"font-size:19px;font-weight:800;margin:18px 0 10px;color:#16233B;\">蜀道集团大疆无人机巡检：采购投资与融资租赁测算</h1><blockquote style=\"background:#EAF1FE;border-left:3px solid #2563EB;border-radius:0 10px 10px 0;padding:12px 14px;margin:14px 0;font-size:13.5px;line-height:1.8;color:#1E3A5F;\">归档日期：2026-08-16</blockquote><blockquote style=\"background:#EAF1FE;border-left:3px solid #2563EB;border-radius:0 10px 10px 0;padding:12px 14px;margin:14px 0;font-size:13.5px;line-height:1.8;color:#1E3A5F;\">关联笔记：蜀道集团低空经济：无人机巡检·招投标采购与产业协作体系, 低空经济专题, 大疆机场3采购NPV测算报告_20260816, 蜀道集团研究线</blockquote><blockquote style=\"background:#EAF1FE;border-left:3px solid #2563EB;border-radius:0 10px 10px 0;padding:12px 14px;margin:14px 0;font-size:13.5px;line-height:1.8;color:#1E3A5F;\">tags: 蜀道集团, 大疆, 无人机巡检, 融资租赁, NPV, 投资测算, 低空经济</blockquote><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">本文把「蜀道集团×大疆无人机巡检」案例（技术方案与算法分层，已另文归档）与「大疆机场3 采购投资的财务测算」合并，回答同一个问题：<b>这套系统不仅技术上成立，账面上买不买得起、怎么付最划算。</b></p><hr style=\"border:none;border-top:1px solid #E3E8F0;margin:18px 0;\"><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">一、案例背景（引用自 蜀道集团低空经济：无人机巡检·招投标采购与产业协作体系）</h2><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">蜀道集团 2025 年启动无人机智能化巡检：<b>大疆机场3（DJI Dock 3）+ Matrice 4TD + 蜀道智巡系统</b>；</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">三层架构：硬件层（大疆）→ 飞控+实时算法层（凌次方，第三方）→ 业务智巡层（蜀道智巡，自研，20+ 类缺陷识别，准确率&gt;90%）；</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">关键认知：<b>飞行级 AI 属大疆，场景级 AI 属适配版</b>——只买大疆通用软件拿不到 90% 识别率，必须做适配（本项目测算中的\"落地价含软件/部署\"即隐含这部分）。</li></ul><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">二、投资测算（2026-08-16 完成，详见 大疆机场3采购NPV测算报告_20260816）</h2><h3 style=\"font-size:15px;font-weight:700;margin:20px 0 8px;color:#1E3A5F;\">已核实基准数据</h3><div style=\"overflow-x:auto;margin:14px 0;\"><table style=\"width:100%;border-collapse:collapse;font-size:12.5px;\"><tbody><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">数据</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">值</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">大疆机场3（含 Matrice 4TD 套装）含税起售价</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">¥130,999</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">大疆机场3（含 Matrice 4D 套装）含税起售价</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">¥117,999</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">市场项目采购单套落地价（含软件/部署）</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">¥13 万 ~ ¥43 万</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">1 年期 LPR</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">3.0%（2026-08，连续多月不变）</td></tr></tbody></table></div><h3 style=\"font-size:15px;font-weight:700;margin:20px 0 8px;color:#1E3A5F;\">三方案 NPV 对比（假设：单套落地 30 万、年运维 3 万、年收益 22.5 万、5 年、贴现率 5%）</h3><div style=\"overflow-x:auto;margin:14px 0;\"><table style=\"width:100%;border-collapse:collapse;font-size:12.5px;\"><tbody><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">方案</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">期初投入</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">NPV</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">IRR</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">判定</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">A. 自购</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">-30 万</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\"><b>+59.1 万</b></td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">59.9%</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">显著为正</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">B. 融资租赁（LPR+150bp，年租 6.8 万）</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">0</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\"><b>+67.8 万</b></td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">不适用</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">NPV 更高</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">C. 维持人工巡检（机会成本）</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">0</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\"><b>-102.3 万</b></td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">—</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">相对损失</td></tr></tbody></table></div><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\"><b>关键结论：</b></p><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>盈亏平衡年收益仅 8.8 万/年</b>——年巡检价值超 8.8 万即盈利，当前假设 22.5 万有 2.5 倍安全垫；</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">敏感性：投资按市场上限 43 万落地 NPV 仍为正（+48.2 万）；收益是最大杠杆变量；贴现率 3%~9% 区间 NPV 恒正；</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\"><b>划不划算由\"采购价 + 收益/成本\"决定（已算出：怎么买都划算）</b>；融资租赁只决定\"付款方式\"。</li></ul><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">三、融资租赁解读（为什么付得少还更划算）</h2><div style=\"overflow-x:auto;margin:14px 0;\"><table style=\"width:100%;border-collapse:collapse;font-size:12.5px;\"><tbody><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">问题</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">答案</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">付清前产权归谁</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\"><b>租赁公司</b>（出资方），不是银行；期满付清 + 名义留购价（1 元/100 元）后转移给你</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">与抵押贷款区别</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">融资租赁=融物（全程产权在出租方，期满转移）；抵押贷款=融资（产权一开始是你的，只是抵押）</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">为什么账面少赚</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">总口径：融资租赁付利息 → 净收益从 10 块降到 6 块量级</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">为什么 NPV 更高</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">折现口径：把 30 万期初支出摊到 5 年，资金时间价值把利息差补回来（+67.8 &gt; +59.1）</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">本质收益</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\"><b>前期现金流压力小</b>，钱腾出来干别的；租赁期折旧/残值风险在租赁公司</td></tr></tbody></table></div><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\"><b>一句话</b>：融资租赁 = 分期付、期满拿产权、账面少赚利息但前期压力小；自购 = 一次付清、无利息、账面多赚但占用 30 万期初资金。</p><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">四、iMA 金融板块蜀道内容索引（2026-08-16 检索确认）</h2><p style=\"font-size:14.5px;line-height:1.85;color:#47536B;margin-bottom:12px;\">iMA 知识库「<b>金融板块</b>」（kb 描述：金融行业分析、基金、融资、产融结合）内收录 6 篇蜀道相关金融内容：</p><div style=\"overflow-x:auto;margin:14px 0;\"><table style=\"width:100%;border-collapse:collapse;font-size:12.5px;\"><tbody><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">标题</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">类型</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">与本项目关联</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">蜀道低空经济基础设施投资分析：盘活高速土地资源的成本与路径（含服务区起降站需求分析）</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">分析</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\"><b>最相关</b>——蜀道低空经济投资 + 高速土地/起降站成本</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">蜀道集团金融版图与天府金控猜想</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">分析</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">蜀道整体金融布局</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">蜀道金租战略定位：内部资金通道（前期以对内服务为主）</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">决策记录</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">蜀道金融租赁公司定位</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">户用光伏融资租赁的 6 个核心难点：蜀道金租是否要做</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">分析</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">融资租赁业务边界案例</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">蜀道难？168 亿创纪录！首单四川高速 REITs 五大问</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">资讯</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">高速 REITs 资本运作</td></tr><tr><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">中国 REITs 市场深度分析：蜀道+万象城+大悦城+凯德+砂之船</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">分析</td><td style=\"border:1px solid #E3E8F0;padding:6px 10px;color:#47536B;line-height:1.6;\">REITs 对标</td></tr></tbody></table></div><blockquote style=\"background:#EAF1FE;border-left:3px solid #2563EB;border-radius:0 10px 10px 0;padding:12px 14px;margin:14px 0;font-size:13.5px;line-height:1.8;color:#1E3A5F;\"><b>读取限制</b>：iMA OpenAPI 仅提供标题/搜索片段，无法读取知识库条目正文。上述索引可在 iMA 客户端内打开原条目查看；若需将正文并入本文，请在 iMA 内导出或告知关键内容。</blockquote><h2 style=\"font-size:16px;font-weight:700;margin:22px 0 10px;color:#1E3A5F;\">五、可执行结论</h2><ul style=\"margin:10px 0 14px;padding-left:20px;\"><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">技术上成立（三层架构、算法归属已厘清）；财务上成立（NPV 恒正、盈亏平衡低）；</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">付款方式建议：<b>现金流充裕 → 自购</b>（省利息）；资金有其他用途 → 融资租赁（NPV 更高、压力小）；</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">若进入实际采购：需确认 ①真实巡检场景与收益口径（替代 1.5 人的假设）②单套落地价（软件/部署/适配）③实际融资利率报价；</li><li style=\"font-size:14px;line-height:1.85;color:#47536B;margin-bottom:6px;\">规模化（多套）需重算：可摊薄运维、有采购议价空间。</li></ul>"};